type ListTransactionsParams struct {
	UserID        int64
	AccountID     uuid.NullUUID
	PayeeID       uuid.NullUUID
	Tag           *string
	FromDate      *time.Time
	ToDate        *time.Time
	Uncategorized bool
	Q             *string
	AfterDate     *time.Time
	AfterID       uuid.NullUUID
	RowLimit      int32
}

// A76: the account filter covers the account and its descendants.
func (q *Queries) ListTransactions(ctx context.Context, arg ListTransactionsParams) ([]LedgerTransaction, error) {
	rows, err := q.db.Query(ctx, listTransactions,
		arg.UserID,
		arg.AccountID,
		arg.PayeeID,
		arg.Tag,
		arg.FromDate,
		arg.ToDate,
		arg.Uncategorized,
		arg.Q,
		arg.AfterDate,
		arg.AfterID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LedgerTransaction
	for rows.Next() {
		var i LedgerTransaction
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Date,
			&i.Description,
			&i.PayeeID,
			&i.BalancingCurrency,
			&i.Origin,
			&i.Version,
			&i.VoidedAt,
			&i.VoidReason,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listVersions = `-- name: ListVersions :many
SELECT
    v.transaction_id, v.version, v.snapshot, v.reason, v.replaced_at
FROM
    ledger_transaction_version v
    JOIN ledger_transaction t ON t.id = v.transaction_id
WHERE
    t.user_id = $1
    AND v.transaction_id = $2
ORDER BY
    v.version
`

type ListVersionsParams struct {
	UserID        int64
	TransactionID uuid.UUID
}

func (q *Queries) ListVersions(ctx context.Context, arg ListVersionsParams) ([]LedgerTransactionVersion, error) {
	rows, err := q.db.Query(ctx, listVersions, arg.UserID, arg.TransactionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LedgerTransactionVersion
	for rows.Next() {
		var i LedgerTransactionVersion
		if err := rows.Scan(
			&i.TransactionID,
			&i.Version,
			&i.Snapshot,
			&i.Reason,
			&i.ReplacedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextPostingPosition = `-- name: NextPostingPosition :one
SELECT
    (coalesce(max(position), -1) + 1)::smallint
FROM
    ledger_posting
WHERE
    transaction_id = $1
`

func (q *Queries) NextPostingPosition(ctx context.Context, transactionID uuid.UUID) (int16, error) {
	row := q.db.QueryRow(ctx, nextPostingPosition, transactionID)
	var column_1 int16
	err := row.Scan(&column_1)
	return column_1, err
}

const reimbursedTotal = `-- name: ReimbursedTotal :one
SELECT
    coalesce(sum(l.amount), 0)::bigint
FROM
    ledger_link l
    JOIN ledger_transaction t ON t.user_id = l.user_id
    AND t.id = l.from_transaction_id
WHERE
    l.user_id = $1
    AND l.to_transaction_id = $2
    AND l.link_type = 'reimbursement_of'
    AND l.from_transaction_id <> $3
    AND t.voided_at IS NULL
`

type ReimbursedTotalParams struct {
	UserID     int64
	OriginID   uuid.UUID
	ExceptFrom uuid.UUID
}

// A117: what the non-voided transactions other than @except_from repay of the expense.
func (q *Queries) ReimbursedTotal(ctx context.Context, arg ReimbursedTotalParams) (int64, error) {
	row := q.db.QueryRow(ctx, reimbursedTotal, arg.UserID, arg.OriginID, arg.ExceptFrom)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const updateTransaction = `-- name: UpdateTransaction :exec
UPDATE ledger_transaction
SET
    date = $1,
    description = $2,
    payee_id = $3,
    balancing_currency = $4,
    origin = $5,
    version = $6,
    updated_at = now()
WHERE
    user_id = $7
    AND id = $8
`

type UpdateTransactionParams struct {
	Date              time.Time
	Description       string
	PayeeID           uuid.NullUUID
	BalancingCurrency string
	Origin            string
	Version           int32
	UserID            int64
	ID                uuid.UUID
}

func (q *Queries) UpdateTransaction(ctx context.Context, arg UpdateTransactionParams) error {
	_, err := q.db.Exec(ctx, updateTransaction,
		arg.Date,
		arg.Description,
		arg.PayeeID,
		arg.BalancingCurrency,
		arg.Origin,
		arg.Version,
		arg.UserID,
		arg.ID,
	)
	return err
}

const voidTransaction = `-- name: VoidTransaction :exec
UPDATE ledger_transaction
SET
    voided_at = $3,
    void_reason = $4,
    updated_at = now()
WHERE
    user_id = $1
    AND id = $2
`

type VoidTransactionParams struct {
	UserID     int64
	ID         uuid.UUID
	VoidedAt   *time.Time
	VoidReason *string
}

func (q *Queries) VoidTransaction(ctx context.Context, arg VoidTransactionParams) error {
	_, err := q.db.Exec(ctx, voidTransaction,
		arg.UserID,
		arg.ID,
		arg.VoidedAt,
		arg.VoidReason,
	)
	return err
}
